    "runs across the open field while the lazy dog sleeps under the warm sun " +
    "and birds fly high above the tall green trees near the flowing river that " +
    "winds through the peaceful valley where deer graze on fresh morning grass " +
    "beneath the clear blue sky filled with soft white clouds drifting slowly past";

var analyzer = new TextAnalyzer(SampleText);

const int WarmupIterations = 1000;
const int Iterations = 500_000;

// Warmup
for (int i = 0; i < WarmupIterations; i++)
{
    Consume(analyzer.AverageWordLength());
    Consume(analyzer.WordLengthHistogram());
    Consume(analyzer.UniqueWordCount());
}

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"Iterations: {Iterations:N0}");
Console.WriteLine();

RunBenchmark("AverageWordLength", () => Consume(analyzer.AverageWordLength()));
RunBenchmark("WordLengthHistogram", () => Consume(analyzer.WordLengthHistogram()));
RunBenchmark("UniqueWordCount", () => Consume(analyzer.UniqueWordCount()));

static void RunBenchmark(string name, Action action)
{
    // Multiple rounds to get stable measurements
    const int rounds = 5;
    double[] nsPerOp = new double[rounds];

    for (int r = 0; r < rounds; r++)
    {
        var sw = Stopwatch.StartNew();
        for (int i = 0; i < Iterations; i++)
            action();
        sw.Stop();
        nsPerOp[r] = (double)sw.Elapsed.TotalNanoseconds / Iterations;
    }

    Array.Sort(nsPerOp);
    double median = nsPerOp[rounds / 2];
    double min = nsPerOp[0];
    double max = nsPerOp[rounds - 1];

    Console.WriteLine($"{name,-25} median: {median,10:F2} ns/op  (min: {min:F2}, max: {max:F2})");
}

